const express = require('express');
const cookieParser = require('cookie-parser');
const { ScalekitClient } = require('@scalekit-sdk/node');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const PORT = 3000;
const CALLBACK_URL = 'http://localhost:3000/callback';
const POST_LOGOUT_URL = 'http://localhost:3000/goodbye';
const SCOPES = ['openid', 'profile', 'email', 'offline_access'];

// Cookie names
const COOKIE_ACCESS_TOKEN = 'accessToken';
const COOKIE_REFRESH_TOKEN = 'refreshToken';
const COOKIE_ID_TOKEN = 'idToken';

// Cookie options – HttpOnly, no Secure (localhost), SameSite=Lax
const COOKIE_OPTS = {
  httpOnly: true,
  sameSite: 'lax',
  path: '/',
};

// ---------------------------------------------------------------------------
// Scalekit SDK client (singleton)
// ---------------------------------------------------------------------------
const scalekit = new ScalekitClient(
  process.env.SCALEKIT_ENV_URL,
  process.env.SCALEKIT_CLIENT_ID,
  process.env.SCALEKIT_CLIENT_SECRET
);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Decode the payload of a JWT without verification.
 * Returns the parsed claims object, or null on failure.
 */
function decodeJwtPayload(token) {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    // Base64url decode the middle segment
    const payload = parts[1];
    const decoded = Buffer.from(
      payload.replace(/-/g, '+').replace(/_/g, '/'),
      'base64'
    ).toString('utf8');
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

/**
 * Set token cookies on the response.
 */
function setTokenCookies(res, accessToken, refreshToken, idToken) {
  res.cookie(COOKIE_ACCESS_TOKEN, accessToken, COOKIE_OPTS);
  res.cookie(COOKIE_REFRESH_TOKEN, refreshToken, COOKIE_OPTS);
  if (idToken) {
    res.cookie(COOKIE_ID_TOKEN, idToken, COOKIE_OPTS);
  }
}

/**
 * Clear all token cookies.
 */
function clearTokenCookies(res) {
  res.clearCookie(COOKIE_ACCESS_TOKEN, COOKIE_OPTS);
  res.clearCookie(COOKIE_REFRESH_TOKEN, COOKIE_OPTS);
  res.clearCookie(COOKIE_ID_TOKEN, COOKIE_OPTS);
}

/**
 * Minimal HTML wrapper.
 */
function htmlPage(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 640px; margin: 60px auto; padding: 0 20px; line-height: 1.6; color: #1a1a1a; }
    h1 { font-size: 1.8rem; }
    .card { border: 1px solid #e2e8f0; border-radius: 8px; padding: 24px; margin: 16px 0; background: #f8fafc; }
    .field { margin: 8px 0; }
    .field-label { font-weight: 600; font-size: 0.85rem; color: #64748b; text-transform: uppercase; }
    .field-value { font-family: "SF Mono", "Fira Code", monospace; font-size: 0.95rem; word-break: break-all; }
    .actions { display: flex; gap: 12px; margin-top: 20px; flex-wrap: wrap; }
    .btn { display: inline-block; padding: 10px 20px; border-radius: 6px; text-decoration: none; font-weight: 500; font-size: 0.95rem; cursor: pointer; border: none; }
    .btn-primary { background: #3b82f6; color: #fff; }
    .btn-primary:hover { background: #2563eb; }
    .btn-secondary { background: #e2e8f0; color: #334155; }
    .btn-secondary:hover { background: #cbd5e1; }
    .btn-danger { background: #ef4444; color: #fff; }
    .btn-danger:hover { background: #dc2626; }
    .welcome { text-align: center; margin-top: 80px; }
    .welcome h1 { font-size: 2.2rem; }
    .welcome p { color: #64748b; font-size: 1.1rem; }
  </style>
</head>
<body>
  ${body}
</body>
</html>`;
}

// ---------------------------------------------------------------------------
// Express app
// ---------------------------------------------------------------------------
const app = express();
app.use(cookieParser());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET / – public landing page
app.get('/', (_req, res) => {
  res.status(200).send(
    htmlPage('Scalekit SaaSKit Demo', `
      <div class="welcome">
        <h1>Scalekit SaaSKit Demo</h1>
        <p>A demonstration of Scalekit authentication with explicit access token refresh.</p>
        <div class="actions" style="justify-content: center;">
          <a class="btn btn-primary" href="/login">Sign in with Scalekit</a>
        </div>
      </div>
    `)
  );
});

// GET /login – build authorize URL via SDK and redirect
app.get('/login', (_req, res) => {
  const authUrl = scalekit.getAuthorizationUrl(CALLBACK_URL, {
    scopes: SCOPES,
  });
  res.redirect(authUrl);
});

// GET /callback – exchange code for tokens, store in HttpOnly cookies, redirect to /dashboard
app.get('/callback', async (req, res) => {
  const { code } = req.query;

  if (!code) {
    return res.redirect('/login');
  }

  try {
    const result = await scalekit.authenticateWithCode(code, CALLBACK_URL);

    setTokenCookies(
      res,
      result.accessToken,
      result.refreshToken,
      result.idToken
    );

    res.redirect('/dashboard');
  } catch (err) {
    console.error('Callback error:', err);
    res.redirect('/login');
  }
});

// GET /dashboard – protected route showing user info and token timestamps
app.get('/dashboard', (req, res) => {
  const accessToken = req.cookies[COOKIE_ACCESS_TOKEN];
  const idToken = req.cookies[COOKIE_ID_TOKEN];

  // If no access token or no id token, redirect to login
  if (!accessToken || !idToken) {
    return res.redirect('/login');
  }

  // Decode the access token to get iat and exp
  const accessClaims = decodeJwtPayload(accessToken);
  // Decode the id token to get the email
  const idClaims = decodeJwtPayload(idToken);

  const email = (idClaims && idClaims.email) ? idClaims.email : 'Unknown';
  const iat = (accessClaims && accessClaims.iat) ? accessClaims.iat : 'N/A';
  const exp = (accessClaims && accessClaims.exp) ? accessClaims.exp : 'N/A';
  const iatDisplay = typeof iat === 'number' ? String(iat) : iat;
  const expDisplay = typeof exp === 'number' ? String(exp) : exp;

  res.status(200).send(
    htmlPage('Dashboard', `
      <h1>Dashboard</h1>
      <div class="card">
        <div class="field">
          <div class="field-label">Signed in as</div>
          <div class="field-value">${email}</div>
        </div>
        <div class="field">
          <div class="field-label">Access Token iat (issued-at)</div>
          <div class="field-value">${iatDisplay}</div>
        </div>
        <div class="field">
          <div class="field-label">Access Token exp (expires-at)</div>
          <div class="field-value">${expDisplay}</div>
        </div>
      </div>
      <div class="actions">
